# ATC clearances, departures, holding and lost communications: 14 CFR 91.123, 91.179, 91.183,
# 91.185; AIM 4-4 (clearances, VFR-on-top), 5-2 (departures, void times, ODPs), 5-3 (reports,
# holding), 5-5-15 (minimum fuel), 4-1-20 (transponder). ACS area III, V.B, VII.A.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Lost communications", "In IMC with no radio, you were told to expect 7,000 ten minutes after departure, and you maintain 5,000 (MEA 4,000). What altitude do you fly?",
      ["7,000 once the 10 minutes pass", "5,000 for the rest of the flight", "4,000, the MEA"],
      "91.185(c)(2) requires the highest of the last assigned altitude, the minimum IFR altitude and the altitude ATC said to expect. Once the 10 minutes pass, the expected 7,000 is the highest, so climb to it."),
    S(1, 2, "Lost communications", "You lose two-way radio in IMC while being radar vectored. Which route do you fly?",
      ["Direct to the fix in the vector clearance", "The route you filed, from the departure fix", "The last assigned heading until VFR is found"],
      "91.185(c)(1)(ii): if being vectored, fly the direct route from the point of failure to the fix, route or airway specified in the vector clearance."),
    S(1, 2, "Holding speeds", "What is the maximum holding airspeed at 5,000 feet MSL, with no other speed charted?",
      ["200 KIAS", "230 KIAS", "265 KIAS"],
      "AIM 5-3-8 gives 200 KIAS from the minimum holding altitude through 6,000 feet, 230 KIAS from 6,001 to 14,000, and 265 KIAS above 14,000."),
    S(1, 3, "Holding entries", "You reach a holding fix heading the same way as the inbound course. Which entry fits?",
      ["Direct", "Parallel", "Teardrop"],
      "Arriving roughly along the inbound course, you cross the fix and simply turn outbound in the direction of the pattern. Teardrop and parallel entries serve arrivals from the other sectors."),
    S(1, 2, "Required reports", "Under 91.183, what must you report to ATC as soon as possible in controlled airspace?",
      ["Unforecast weather conditions", "Every change of heading", "Each frequency change you make"],
      "91.183 requires reports of designated reporting points (when not in radar contact), any unforecast weather encountered and any other safety information."),
    S(1, 3, "VFR-on-top", "In which airspace can't you operate VFR-on-top?",
      ["Class A", "Class E", "Class G"],
      "AIM 4-4-8: VFR-on-top is not permitted in Class A airspace, where all flight is IFR at assigned altitudes."),
    S(1, 2, "Departure procedures", "Unless a departure procedure says otherwise, how high above the departure end must you be before turning?",
      ["400 feet", "500 feet", "1,000 feet"],
      "AIM 5-2-9: obstacle clearance assumes crossing the runway end at 35 feet and climbing to 400 feet above it before the first turn, then at least the standard climb gradient."),
    S(1, 2, "Clearance void time", "You are not airborne by your clearance void time. What must you do?",
      ["Tell ATC your intentions soon", "Depart anyway and call once airborne", "Wait 30 minutes, then depart"],
      "AIM 5-2-7: a pilot who doesn't depart before the void time must advise ATC as soon as possible, within the time ATC gives, which can't exceed 30 minutes."),
    # ---------- Practice Test 2 ----------
    S(2, 3, "Lost communications", "No radio, IMC. You reach your clearance limit, an approach fix, with no EFC. When do you start the approach?",
      ["As close as possible to your ETA", "At once on arrival over the fix", "After one full turn in the holding pattern"],
      "91.185(c)(3)(i): with the limit an approach fix and no EFC received, begin descent and approach as close as possible to the ETA from the filed or amended time en route."),
    S(2, 2, "Lost communications", "Your radio fails in IMC, then you break out into VFR conditions. What does 91.185 require?",
      ["Continue VFR and land when practicable", "Climb back into IMC and fly the filed route", "Squawk 7700 and hold at the next fix"],
      "91.185(b): if VFR conditions are met after the failure, continue the flight under VFR and land as soon as practicable."),
    S(2, 2, "Holding timing", "At 16,000 feet MSL with no DME, how long is the inbound leg of a holding pattern?",
      ["1 1/2 minutes", "1 minute", "2 minutes"],
      "AIM 5-3-8: inbound legs are 1 minute at or below 14,000 feet MSL and 1 1/2 minutes above 14,000 feet."),
    S(2, 2, "Holding speeds", "When should you begin slowing for an expected holding pattern?",
      ["3 minutes or less from the fix", "After crossing the holding fix", "10 minutes before the fix"],
      "AIM 5-3-8 expects a speed reduction once within 3 minutes of the clearance limit, so the airplane crosses the fix at or below the maximum holding airspeed."),
    S(2, 2, "Required reports", "Which report does the AIM require in or out of radar contact?",
      ["Leaving an assigned altitude", "Tuning each new VOR on the route", "Passing every intersection"],
      "AIM 5-3-3 lists reports required at all times, including vacating an assigned altitude, being unable to climb or descend at 500 fpm, a missed approach and a TAS change of 5% or 10 knots."),
    S(2, 3, "IFR cruising altitudes", "IFR in uncontrolled airspace below 18,000 feet on a magnetic course of 200 degrees, which altitude fits?",
      ["6,000 MSL", "7,000 MSL", "6,500 MSL"],
      "91.179(b): on magnetic courses of 180 to 359 degrees, fly even thousands. 6,000 fits; 6,500 is a VFR altitude."),
    S(2, 2, "Cruise clearance", "What does a cruise clearance to 8,000 feet allow you to do?",
      ["Choose any altitude up to 8,000", "Climb above 8,000 at your discretion", "Fly VFR-on-top below 8,000"],
      "A cruise clearance assigns a block from the minimum IFR altitude up to the stated altitude, here 8,000. Once you report leaving an altitude in the block, you can't return to it without a new clearance."),
    S(2, 2, "Minimum fuel", "What does a 'minimum fuel' advisory tell ATC?",
      ["You can accept no undue delay", "You are declaring an emergency", "You need priority to land now"],
      "AIM 5-5-15: minimum fuel means you can't accept undue delay at the destination. It is not an emergency; if fuel becomes critical, declare one."),
    # ---------- Drill only ----------
    S(0, 2, "Holding speeds", "From 6,001 to 14,000 feet MSL, the standard maximum holding airspeed is:",
      ["230 KIAS", "200 KIAS", "265 KIAS"],
      "AIM 5-3-8 sets 230 KIAS from 6,001 to 14,000 feet, though a charted pattern there may be limited to 210 KIAS."),
    S(0, 2, "Holding instructions", "Unless the pattern is charted, what must ATC give with a hold when delay is expected?",
      ["Full instructions and an EFC", "Only the holding fix and altitude", "Only the inbound course and turns"],
      "AIM 5-3-8: when delay is expected at a fix other than the destination, ATC issues complete holding instructions, an EFC time and an estimate of further delay."),
    S(0, 2, "Holding timing", "When does timing of the outbound leg start?",
      ["Over or abeam the fix, whichever is later", "When the turn outbound starts", "When the needle centers on the inbound course"],
      "AIM 5-3-8: outbound timing begins over or abeam the fix, whichever occurs later; if abeam can't be found, start when the turn outbound is complete."),
    S(0, 3, "Lost communications", "No radio, IMC. Your clearance limit is not an approach fix and ATC gave an EFC. When do you leave it?",
      ["At the EFC time", "On arrival over the fix", "At your filed ETA"],
      "91.185(c)(3)(ii): leave a clearance limit that is not an approach fix at the EFC time if one was received, then proceed to an approach fix and begin the approach near the ETA."),
    S(0, 2, "Transponder codes", "Which transponder code signals a radio failure?",
      ["7600", "7700", "7500"],
      "7600 indicates lost communications, 7700 an emergency and 7500 unlawful interference. When changing codes, avoid passing through these by mistake."),
    S(0, 2, "Required reports", "When must you tell ATC you can't keep up a climb or descent rate?",
      ["Below 500 fpm", "Below 300 fpm", "Below 1,000 fpm"],
      "AIM 5-3-3 asks for a report whenever you are unable to climb or descend at a rate of at least 500 feet per minute."),
    S(0, 2, "Non-radar reports", "Outside radar contact, which extra report does the AIM require on a nonprecision approach?",
      ["Leaving the FAF inbound", "Turning base for the runway", "Seeing the approach lights"],
      "AIM 5-3-3 lists added non-radar reports: leaving the FAF inbound on a nonprecision approach (or the outer marker on a precision approach) and corrected estimates off by more than 2 minutes."),
    S(0, 3, "VFR-on-top", "Under a VFR-on-top authorization, which rule still applies?",
      ["Minimum IFR altitudes", "Your filed IFR altitude", "Class A airspace entry"],
      "AIM 4-4-8: VFR-on-top pilots fly VFR altitudes and cloud clearances but must still follow IFR rules such as minimum IFR altitudes, reports and the clearance. It is not allowed in Class A."),
    S(0, 2, "Deviation in emergency", "You deviate from a clearance to avoid a TCAS resolution advisory. What must you do?",
      ["Tell ATC as soon as possible", "File a NASA report within 10 days", "Squawk 7700 until landing"],
      "91.123(c): a pilot who deviates from a clearance in an emergency or in response to a TCAS RA must notify ATC of the deviation as soon as possible."),
    S(0, 2, "Departure procedures", "A SID climb gradient is 300 feet per NM and your groundspeed is 120 knots. About what climb rate is needed?",
      ["600 fpm", "360 fpm", "400 fpm"],
      "Climb rate equals gradient times groundspeed in NM per minute: 120 knots is 2 NM per minute, so 300 x 2 = 600 fpm."),
]
